import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import ProductCard from "../components/ProductCard";
import "./Dashboard.css";

function Dashboard() {
    const navigate = useNavigate();
    const [user, setUser] = useState(null);

    // Data dummy products
    const products = [
        {
            id: 1,
            title: "Buku React Dasar",
            description: "Belajar React dari nol hingga mahir",
            price: "50.000",
            image: "data:image/jpeg;base64,"
        },
        {
            id: 2,
            title: "Buku JavaScript Modern",
            description: "Panduan JavaScript ES6+ untuk pemula",
            price: "75.000",
            image: "data:image/jpeg;base64,"
        },
        {
            id: 3,
            title: "Buku PostgreSQL",
            description: "Database untuk Backend Developer",
            price: "65.000",
            image: "data:image/jpeg;base64,"
        },
        {
            id: 4,
            title: "Node.js Design Patterns",
            description: "Pola desain untuk aplikasi Node.js",
            price: "85.000",
            image: "data:image/jpeg;base64,"
        }
    ];

    useEffect(() => {
        // Cek apakah user sudah login
        const token = localStorage.getItem("token");
        const userData = localStorage.getItem("user");
        
        if (!token) {
            navigate("/login");
        }
        
        if (userData) {
            setUser(JSON.parse(userData));
        }
    }, [navigate]);

    const handleLogout = () => {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        navigate("/login");
    };

    return (
        <div className="dashboard-container">
            <div className="dashboard-header">
                <h1>Dashboard Produk</h1>
                <div className="user-info">
                    <span>Selamat datang, {user?.username || "Admin"}!</span>
                    <button onClick={handleLogout} className="logout-btn">Logout</button>
                </div>
            </div>
            
            <div className="product-grid">
                {products.map(product => (
                    <ProductCard 
                        key={product.id}
                        title={product.title}
                        description={product.description}
                        price={product.price}
                        image={product.image}
                    />
                ))}
            </div>
        </div>
    );
}

export default Dashboard;